const $=id=>document.getElementById(id);let token='',page=1,total=0,selected=null,activityPage=1,activityTotal=0;
const notice=s=>$('notice').textContent=s;
const api=async(path,method='GET',data)=>{const r=await fetch('/api/admin/'+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d};
const safe=async fn=>{try{await fn()}catch(e){notice(e.message)}};
function cell(row,t){const x=document.createElement('td');x.textContent=t;row.append(x);return x}
function button(text,fn){const b=document.createElement('button');b.textContent=text;b.type='button';b.onclick=()=>safe(fn);return b}
function options(id,items,label){const s=$(id);s.replaceChildren(new Option('Sélectionner',''));for(const x of items)s.append(new Option(label(x),x.id))}
async function lookup(){const t=token;const [q,c]=await Promise.all([api('missions/eligible?page='+encodeURIComponent($('quote-page').value)),api('consultants?'+new URLSearchParams({q:$('search').value,status:'DISPONIBLE'}))]);if(!token||t!==token)return;options('quote',q.items,x=>x.company+' / '+x.title);options('consultant',c.items,x=>x.name+' / '+x.role);notice('Choix actualisés (25 maximum par recherche).')}
async function load(){const t=token,d=await api('missions?page='+page);if(!token||t!==token)return;total=d.total;$('rows').replaceChildren();for(const m of d.items){const r=document.createElement('tr');cell(r,m.company+' / '+m.title+' / '+m.team.map(x=>x.name).join(', '));cell(r,m.mission_status+' · échéance '+m.end_date);cell(r,m.worked+' / '+m.billable);cell(r,m.actual_cost+' '+m.currency);cell(r,m.billable_revenue===null?'Non calculé':m.billable_revenue+' '+m.currency);cell(r,(m.actual_margin??'Non calculée')+' / '+m.planned_margin+' '+m.currency);const td=cell(r,'');td.append(button('Contrat / renouvellement',()=>openContract(m)));td.append(button('CRA',async()=>{selected=m;options('cra-consultant',m.team,x=>x.name);$('cra-consultant').value=m.consultant_id;activityPage=1;$('cra').hidden=false;$('cra-title').textContent='CRA — '+m.title;$('activity').hidden=m.mission_status!=='ACTIVE';await entries()}));if(m.mission_status==='ACTIVE')td.append(button('Ajouter le consultant sélectionné',async()=>{const id=$('consultant').value;if(!id)throw Error('Sélectionnez un consultant dans le formulaire de création.');if(!confirm('Ajouter ce consultant à la mission pour toute sa durée ?'))return;await api('missions/'+m.mission_id+'/team','POST',{consultant_id:id});selected=null;$('cra').hidden=true;await load();notice('Consultant ajouté.')}));if(m.mission_status==='ACTIVE')td.append(button('Clôturer',async()=>{if(!confirm('Clôturer définitivement cette mission ?'))return;await api('missions/'+m.mission_id,'PATCH',{status:'TERMINE'});selected=null;$('cra').hidden=true;await load();notice('Mission clôturée.')}));$('rows').append(r)}$('page').textContent='Page '+page+' · '+total+' mission(s)';$('prev').disabled=page<=1;$('next').disabled=page*25>=total}
async function entries(){if(!selected)return;const id=selected.mission_id,t=token,d=await api('missions/'+id+'/activity?page='+activityPage);if(!token||t!==token||selected?.mission_id!==id)return;activityTotal=d.total;$('entries').replaceChildren();for(const x of d.items){const r=document.createElement('tr');for(const v of [x.work_date+' / '+(selected.team.find(c=>c.id===x.consultant_id)?.name||'Consultant'),x.worked+' / '+x.billable,x.expenses,x.description,x.status])cell(r,v);const td=cell(r,'');if(x.status==='SOUMIS')for(const status of ['VALIDE','REFUSE'])td.append(button(status,async()=>{await api('missions/activity/'+x.id,'PATCH',{status});await entries();await load();notice('CRA traité.')}));$('entries').append(r)}$('cra-page').textContent='Page '+activityPage+' · '+activityTotal+' CRA';$('cra-prev').disabled=activityPage<=1;$('cra-next').disabled=activityPage*25>=activityTotal}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';try{await load();await lookup();$('workspace').hidden=false;$('login').hidden=true}catch(e){token='';notice(e.message)}};
$('logout').onclick=()=>{token='';selected=null;$('workspace').hidden=true;$('cra').hidden=true;$('login').hidden=false;for(const id of ['rows','entries','quote','consultant'])$(id).replaceChildren();$('mission').reset();$('activity').reset();notice('Déconnecté.')};
$('lookup').onclick=()=>safe(lookup);$('mission').onsubmit=e=>{e.preventDefault();safe(async()=>{const submit=e.submitter;submit.disabled=true;try{await api('missions','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await lookup();page=1;await load();notice('Mission créée.')}finally{submit.disabled=false}})};
$('activity').onsubmit=e=>{e.preventDefault();if(!selected)return;safe(async()=>{const submit=e.submitter;submit.disabled=true;try{await api('missions/'+selected.mission_id+'/activity','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();$('cra-consultant').value=selected.consultant_id;activityPage=1;await entries();notice('CRA soumis.')}finally{submit.disabled=false}})};
$('prev').onclick=()=>{if(page>1){page--;safe(load)}};$('next').onclick=()=>{if(page*25<total){page++;safe(load)}};$('cra-prev').onclick=()=>{if(activityPage>1){activityPage--;safe(entries)}};$('cra-next').onclick=()=>{if(activityPage*25<activityTotal){activityPage++;safe(entries)}};
const craLabel=document.createElement('label');craLabel.textContent='Consultant du CRA';const craSelect=document.createElement('select');craSelect.name='consultant_id';craSelect.id='cra-consultant';craSelect.required=true;craLabel.append(craSelect);$('activity').prepend(craLabel);
const contractPanel=document.createElement('section');contractPanel.hidden=true;const contractTitle=document.createElement('h2');contractTitle.textContent='Contrat et renouvellements';const contractInfo=document.createElement('p');const contractForm=document.createElement('form');contractForm.className='editor';const contractHistory=document.createElement('div');let contractMission=null,contractEpoch=0;
for(const [name,label,type,max] of [['new_end','Nouvelle échéance','date',10],['reference','Référence de l’avenant','text',180],['reason','Motif','text',1000]]){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.name=name;i.type=type;i.required=true;i.maxLength=max;l.append(i);contractForm.append(l)}
const sendRenewal=document.createElement('button');sendRenewal.textContent='Soumettre le renouvellement';contractForm.append(sendRenewal);contractPanel.append(contractTitle,contractInfo,contractForm,contractHistory);$('workspace').append(contractPanel);
async function openContract(m){contractMission=m;const epoch=++contractEpoch,t=token;const d=await api('missions/'+m.mission_id+'/renewals');if(!token||token!==t||epoch!==contractEpoch)return;contractPanel.hidden=false;contractInfo.textContent=m.title+' · '+d.contract.contract_ref+' · échéance '+d.contract.end_date+' · '+(d.remaining_days<0?'Expiré':d.remaining_days<=30?'À renouveler sous 30 jours':'En cours');contractForm.hidden=!d.can_request||d.contract.status!=='ACTIVE'||d.items.some(x=>x.status==='SOUMIS');contractForm.elements.new_end.min=d.contract.end_date;contractHistory.replaceChildren();for(const x of d.items){const p=document.createElement('p');p.textContent=x.old_end+' → '+x.new_end+' · '+x.reference+' · '+x.reason+' · '+x.status+' · '+x.requester+(x.reviewer?' / '+x.reviewer:'');if(d.can_review&&x.status==='SOUMIS'&&x.requester!==d.actor&&d.contract.status==='ACTIVE')for(const status of ['VALIDE','REFUSE'])p.append(button(status,async()=>{await api('missions/'+m.mission_id+'/renewals/'+x.id,'PATCH',{status});await load();await openContract(m);notice('Renouvellement traité.')}));contractHistory.append(p)}if(!d.items.length)contractHistory.textContent='Aucun renouvellement.';}
contractForm.onsubmit=e=>{e.preventDefault();if(!contractMission)return;safe(async()=>{const m=contractMission;sendRenewal.disabled=true;try{await api('missions/'+m.mission_id+'/renewals','POST',Object.fromEntries(new FormData(contractForm)));contractForm.reset();await openContract(m);notice('Renouvellement soumis.')}finally{sendRenewal.disabled=false}})};
$('logout').addEventListener('click',()=>{contractEpoch++;contractMission=null;contractPanel.hidden=true;contractHistory.replaceChildren();contractInfo.textContent='';contractForm.reset();});
